/* Builds pd-bundle.js: every site script in one file, in the order the site loads them.
   Each script is a self-contained IIFE, so each is wrapped in try/catch: one failing script can't stop the rest.
   Run: node build-bundle.js */
const fs=require("fs");
const FILES=["pd-cover.js","pd-grid.js","pd-text.js","pd-route.js","pd-sfx.js","pd-nyp.js","pd-sheet.js",
  "pd-share.js","pd-ad.js","pd-cam.js","pd-play.js","pd-link.js","pd-shop.js","pd-ux.js","pd-premium.js","pd-press.js","pd-svcwork.js","pd-dock.js"];
const out=["/* pd-bundle.js — generated by build-bundle.js from: "+FILES.join(", ")+". Edit those files, not this one. */"];
for(const f of FILES)out.push(`/* ===== ${f} ===== */\ntry{\n${fs.readFileSync(f,"utf8").trim()}\n}catch(e){console.error("${f}",e)}`);
fs.writeFileSync("pd-bundle.js",out.join("\n")+"\n");
console.log("pd-bundle.js",fs.statSync("pd-bundle.js").size,"bytes from",FILES.length,"files");
